type FooterProps = Pick<SignInPageLayoutProps, 'navigateFocus'>;

type FooterColumnRow = (LinkProps | PressProps) & {
    translationPath: TranslationPaths;
};

type FooterColumnData = {
    translationPath: TranslationPaths;
